<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';require __DIR__.'/feature_helpers.php';saas_require_login();$tourId=saas_require_tour();saas_require_permission('settings.manage');$db=saas_db();$key=(string)($_GET['feature']??$_POST['feature_key']??'');$catalog=saas_feature_catalog();if(!isset($catalog[$key])){http_response_code(404);exit('Feature not found.');}$feature=saas_feature($tourId,$key);if(!$feature){$q=$db->prepare('INSERT INTO tour_features(tour_id,feature_key,enabled,config_json) VALUES(?,?,1,?)');$q->execute([$tourId,$key,json_encode(['label'=>$catalog[$key]['label'],'description'=>$catalog[$key]['description']])]);$feature=saas_feature($tourId,$key);}$error='';$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$action=(string)($_POST['action']??'');if($action==='add'){ $label=trim((string)$_POST['option_label']);$value=trim((string)$_POST['option_value']);$price=max(0,(float)$_POST['price']);if($label==='')throw new RuntimeException('Option label is required.');$optionKey=saas_slug($label);$q=$db->prepare('INSERT INTO tour_feature_options(tour_feature_id,option_key,option_label,option_value,price,sort_order) VALUES(?,?,?,?,?,?)');$q->execute([(int)$feature['id'],$optionKey,$label,$value?:null,$price,(int)$_POST['sort_order']]);$ok='Option added.';}elseif($action==='delete'){ $id=(int)$_POST['option_id'];$q=$db->prepare('UPDATE tour_feature_options SET status="INACTIVE" WHERE id=? AND tour_feature_id=?');$q->execute([$id,(int)$feature['id']]);$ok='Option disabled.';}}catch(Throwable $e){$error=$e->getMessage();}}$options=saas_feature_options((int)$feature['id']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Feature Options</title><style>body{font-family:system-ui;background:#f5f7fb;color:#172033;margin:0}.wrap{max-width:850px;margin:30px auto;padding:0 18px}.box{background:#fff;padding:20px;border-radius:14px;margin:16px 0;box-shadow:0 5px 20px #0001}input,button{box-sizing:border-box;width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:8px;font:inherit}button{background:#172033;color:#fff;border:0;font-weight:700;margin-top:12px}.grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:10px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eee;text-align:left}.danger{background:#b42318}.ok{background:#ecfdf3;color:#067647;padding:10px;border-radius:8px}.err{background:#fef3f2;color:#b42318;padding:10px;border-radius:8px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="features.php">← Features</a></p><h1><?=saas_h($catalog[$key]['label'])?> options</h1><?php if($ok):?><div class="ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="err"><?=saas_h($error)?></div><?php endif;?><section class="box"><h2>Add option</h2><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="feature_key" value="<?=saas_h($key)?>"><input type="hidden" name="action" value="add"><div class="grid"><input name="option_label" placeholder="e.g. Chicken Meal" required><input name="option_value" placeholder="Code/details"><input name="price" type="number" min="0" step="0.01" value="0"></div><input name="sort_order" type="number" value="0" placeholder="Sort order"><button>Add option</button></form></section><section class="box"><h2>Active options</h2><table><tr><th>Label</th><th>Value</th><th>Price</th><th></th></tr><?php foreach($options as $o):?><tr><td><?=saas_h($o['option_label'])?></td><td><?=saas_h($o['option_value']??'')?></td><td><?=number_format((float)$o['price'],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="feature_key" value="<?=saas_h($key)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="option_id" value="<?=$o['id']?>"><button class="danger">Disable</button></form></td></tr><?php endforeach;?></table><?php if(!$options):?><p>No options configured yet.</p><?php endif;?></section></main></body></html>